@singledispatch
def area(shape, *, total=0.0):
    raise NotImplementedError(f"no area for {type(shape).__name__}")   # default case

@area.register
def _(shape: Circle, *, total=0.0) -> float:
    return math.pi * shape.radius ** 2

@area.register(UnionShape)     # new element kind: register it, touch nothing else
def _(shape, *, total=0.0) -> float:
    return area(shape.a, total=total) + area(shape.b, total=total)
